/* ===================== BÀI 52 · Máy tính giám sát và Modbus RTU tùy chọn ===================== */
/* Bài 52 · Máy tính giám sát và Modbus RTU tùy chọn (AMTS-EMB-001-M13-L04, MC51-052) — sinh bởi tools/author/mcu8051/l52.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const P52=[{"label":"Ví dụ: Lệnh ASCII R2 và câu trả lời","code":"; Ví dụ 1: lệnh ASCII \"R2<CR>\" -> trả lời \"=3C<CR><LF>\"\n; Bộ đệm 40H..42H giả định đã nhận đủ dòng lệnh. 11,0592 MHz,\n; UART chế độ 1, 9600 baud (TH1 = FDH, SMOD = 0)\n        ORG     0000H\n        MOV     40H,#'R'                ; giả lập: dòng lệnh đã nhận\n        MOV     41H,#'2'\n        MOV     42H,#0DH\n        MOV     52H,#3CH                ; thanh ghi 2 của máy (giả định)\n        MOV     TMOD,#20H\n        MOV     TH1,#0FDH\n        MOV     SCON,#40H\n        SETB    TR1\n        MOV     A,41H                   ; '2' -> 2 -> địa chỉ 52H\n        ANL     A,#07H\n        ADD     A,#50H\n        MOV     R0,A\n        MOV     A,#'='\n        ACALL   GUI\n        MOV     A,@R0                   ; giá trị cần trả\n        SWAP    A\n        ACALL   HEX                     ; chữ số hex cao\n        MOV     A,@R0\n        ACALL   HEX                     ; chữ số hex thấp\n        MOV     A,#0DH\n        ACALL   GUI\n        MOV     A,#0AH\n        ACALL   GUI\n        SJMP    $\nHEX:    ANL     A,#0FH                  ; 0..15 -> '0'..'9','A'..'F'\n        ADD     A,#0F6H                 ; CY = 1 khi A >= 10\n        JNC     SO\n        ADD     A,#07H\nSO:     ADD     A,#3AH\nGUI:    MOV     SBUF,A                  ; gửi một byte, chờ phát xong\n        JNB     TI,$\n        CLR     TI\n        RET\n        END\n","note":"Đoán trước: cửa sổ UART hiện gì? (“=3C” rồi xuống dòng.) HEX đổi 0…15 thành '0'…'9', 'A'…'F' không cần bảng: ADD A,#0F6H làm CY = 1 khi A ≥ 10, thêm 7 để nhảy qua các ký tự giữa '9' và 'A'. Gửi xong cả dòng mất khoảng 5 000 chu kỳ máy — gần như toàn bộ là chờ TI.","dev":{"led":true},"fosc":11059200,"speed":"real","watch":{"title":"Biến theo dõi","vars":[["40H lệnh",64,"hex"],["41H số",65,"hex"],["R0 (địa chỉ)",0,"hex"],["52H giá trị",82,"hex"]],"hint":"Xem cửa sổ UART ở phần Kết quả: “=3C” rồi xuống dòng. Mỗi byte chờ TI khoảng 1 ms (960 chu kỳ máy)."}},{"label":"Ví dụ: Bộ phân tích lệnh là máy trạng thái","code":"; Ví dụ 2: bộ phân tích lệnh không chặn = máy trạng thái\n; Mỗi tick nhận tối đa 1 byte (giả lập: bảng RX). Lệnh hợp lệ:\n; 'R' hoặc 'W', một chữ số '0'..'7', rồi CR (0DH)\nPST     DATA    30H                     ; 0 CHỜ_LỆNH 1 CHỜ_SỐ 2 CHỜ_CR\nCMD     DATA    31H                     ; lệnh đang nhận\nREG     DATA    32H                     ; số thanh ghi\nNOK     DATA    33H                     ; số khung hợp lệ\nNERR    DATA    34H                     ; số khung bị loại\n        ORG     0000H\n        MOV     R7,#0\nBUOC:   MOV     A,R7                    ; \"byte vừa nhận\" của tick này\n        MOV     DPTR,#RX\n        MOVC    A,@A+DPTR\n        JZ      XONG                    ; 00H: hết dữ liệu giả lập\n        INC     R7\n        MOV     R2,A\n        MOV     A,PST\n        JZ      S0\n        DEC     A\n        JZ      S1\n        CJNE    R2,#0DH,LOI             ; S2: chỉ nhận CR\n        INC     NOK                     ; đủ khung: báo cho tác vụ xử lý\n        SJMP    VE\nS1:     MOV     A,R2                    ; chữ số '0'..'7'?\n        ADD     A,#-'0'\n        CJNE    A,#8,$+3                ; CY = 1 khi 0..7 (và byte >= '0')\n        JNC     LOI\n        MOV     REG,A\n        MOV     PST,#2\n        SJMP    BUOC\nS0:     CJNE    R2,#'R',S0W\n        SJMP    S0OK\nS0W:    CJNE    R2,#'W',BUOC            ; byte rác khi chờ lệnh: bỏ qua\nS0OK:   MOV     CMD,R2\n        MOV     PST,#1\n        SJMP    BUOC\nLOI:    INC     NERR                    ; khung sai: về CHỜ_LỆNH\nVE:     MOV     PST,#0\n        SJMP    BUOC\nXONG:   SJMP    $\nRX:     DB      'R','2',0DH,'Q','W','9',0DH,'R','7',0DH,0\n        END\n","note":"Bấm Từng bước và xem bảng Sơ đồ trạng thái: R 2 CR đi đủ ba trạng thái (NOK = 1); 'Q' bị bỏ qua ở CHỜ_LỆNH; 'W' rồi '9' là lỗi (NERR = 1), CR theo sau thành rác; cuối cùng R 7 CR hợp lệ: NOK = 2, REG = 7, CMD = 'R' (52H).","dev":{"led":true},"fosc":11059200,"watch":{"title":"Sơ đồ trạng thái","state":48,"states":["CHỜ_LỆNH","CHỜ_SỐ","CHỜ_CR"],"edges":[[0,1,"'R' hoặc 'W' / CMD = byte"],[1,2,"'0'..'7' / REG = số"],[2,0,"CR / NOK + 1"],[1,0,"byte sai / NERR + 1"],[2,0,"byte khác CR / NERR + 1"]],"vars":[["R2 (byte)",2,"hex"],["CMD",49,"hex"],["REG",50,"dec"],["NOK",51,"dec"],["NERR",52,"dec"]],"hint":"Mỗi bước nhận đúng một byte: R 2 CR (hợp lệ), Q (rác, bỏ qua), W 9 (số sai → lỗi), CR (rác), R 7 CR (hợp lệ)."}},{"label":"Ví dụ: CRC-16 Modbus của một khung","code":"; Ví dụ 3: CRC-16 Modbus của khung 01 03 00 00 00 01\n; Đa thức đảo A001H, đầu FFFFH; kết quả 30H thấp, 31H cao\n        ORG     0000H\n        MOV     R0,#40H                 ; chép khung mẫu vào 40H..45H\n        MOV     DPTR,#KHUNG\n        MOV     R7,#6\nCHEP:   CLR     A\n        MOVC    A,@A+DPTR\n        MOV     @R0,A\n        INC     R0\n        INC     DPTR\n        DJNZ    R7,CHEP\n        MOV     R2,#0FFH                ; CRC = FFFFH (R3:R2)\n        MOV     R3,#0FFH\n        MOV     R0,#40H\n        MOV     R7,#6                   ; số byte\nVBYTE:  MOV     A,@R0\n        XRL     A,R2                    ; byte thấp của CRC XOR dữ liệu\n        MOV     R2,A\n        MOV     R6,#8\nVBIT:   CLR     C                       ; dịch phải CRC 16 bit\n        MOV     A,R3\n        RRC     A\n        MOV     R3,A\n        MOV     A,R2\n        RRC     A\n        MOV     R2,A\n        JNC     KHONG                   ; bit bị đẩy ra = 1 thì XOR A001H\n        XRL     02H,#01H                ; R2 (địa chỉ 02H) ^= 01H\n        XRL     03H,#0A0H               ; R3 (địa chỉ 03H) ^= A0H\nKHONG:  DJNZ    R6,VBIT\n        INC     R0\n        DJNZ    R7,VBYTE\n        MOV     30H,R2                  ; gửi đi: byte thấp trước\n        MOV     31H,R3\n        SJMP    $\nKHUNG:  DB      01H,03H,00H,00H,00H,01H\n        END\n","note":"Từng bước trong vòng VBIT: R3:R2 dịch phải 1 bit; khi CY = 1 thì XOR A001H. Kết thúc CRC = 0A84H; byte thấp 84H vào 30H, byte cao 0AH vào 31H — khung gửi đi là 01 03 00 00 00 01 84 0A.","dev":{"led":true},"fosc":11059200,"watch":{"title":"Biến theo dõi","vars":[["R3 CRC cao",3,"hex"],["R2 CRC thấp",2,"hex"],["R6 (bit)",6,"dec"],["R7 (byte)",7,"dec"],["R0",0,"hex"]],"hint":"Bấm Từng bước trong vòng VBIT: R3:R2 dịch phải 1 bit; khi bit đẩy ra (CY) = 1 thì XOR với A001H. Kết thúc: CRC = 0A84H, gửi 84 rồi 0A."}},{"label":"Bẫy: Gửi byte cao của CRC trước","code":"; Bẫy: bên gửi đặt byte CAO của CRC trước (sai thứ tự Modbus)\n; Bên nhận tính CRC trên cả khung kể cả 2 byte CRC:\n; đúng thứ tự (thấp trước) thì kết quả phải là 0000H\n        ORG     0000H\n        MOV     R0,#40H                 ; chép khung nhận được vào 40H..47H\n        MOV     DPTR,#KHUNG\n        MOV     R7,#8\nCHEP:   CLR     A\n        MOVC    A,@A+DPTR\n        MOV     @R0,A\n        INC     R0\n        INC     DPTR\n        DJNZ    R7,CHEP\n        MOV     R0,#40H\n        MOV     R7,#8                   ; CRC trên 8 byte\n        ACALL   CRC16\n        MOV     30H,R2\n        MOV     31H,R3\n        MOV     A,R2                    ; khung tốt khi R3:R2 = 0000H\n        ORL     A,R3\n        MOV     32H,#0\n        JNZ     XONG                    ; khác 0: loại khung, không trả lời\n        MOV     32H,#1\nXONG:   SJMP    $\n; CRC16: R0 = địa chỉ, R7 = số byte -> R3:R2 (đầu FFFFH)\nCRC16:  MOV     R2,#0FFH\n        MOV     R3,#0FFH\nCB:     MOV     A,@R0\n        XRL     A,R2\n        MOV     R2,A\n        MOV     R6,#8\nCBIT:   CLR     C\n        MOV     A,R3\n        RRC     A\n        MOV     R3,A\n        MOV     A,R2\n        RRC     A\n        MOV     R2,A\n        JNC     CK\n        XRL     02H,#01H\n        XRL     03H,#0A0H\nCK:     DJNZ    R6,CBIT\n        INC     R0\n        DJNZ    R7,CB\n        RET\nKHUNG:  DB      01H,03H,00H,00H,00H,01H,0AH,84H\n        END\n","note":"Bên gửi đặt 0A trước 84. Bên nhận tính CRC trên cả 8 byte được C4E5H ≠ 0000H nên 32H = 00H: loại khung, không trả lời. Đổi DB cuối thành 84H,0AH rồi chạy lại: R3:R2 = 0000H, 32H = 01H.","dev":{"led":true},"fosc":11059200,"watch":{"title":"Biến theo dõi","vars":[["R3 CRC cao",3,"hex"],["R2 CRC thấp",2,"hex"],["32H khung tốt?",50,"hex"]],"hint":"Khung đúng (… 84 0A) cho CRC cả khung = 0000H. Đảo hai byte (… 0A 84) cho C4E5H: bên nhận loại khung, máy chủ chờ hết thời gian."}},{"label":"Ví dụ: Chân DE của RS-485 bán song công","code":"; Ví dụ 5: RS-485 bán song công, chân DE = P1.0 (giả định)\n; DE = 1: phát; DE = 0: nhận. 11,0592 MHz, 9600 baud, 8N1\n        ORG     0000H\n        CLR     P1.0                    ; mặc định: nhận (nhả đường dây)\n        MOV     TMOD,#20H\n        MOV     TH1,#0FDH\n        MOV     SCON,#40H\n        SETB    TR1\n        SETB    P1.0                    ; giành đường dây để phát\n        MOV     R0,#0\n        MOV     DPTR,#TL\nGUI:    MOV     A,R0\n        MOVC    A,@A+DPTR\n        JZ      HET\n        MOV     SBUF,A\n        JNB     TI,$\n        CLR     TI\n        INC     R0\n        SJMP    GUI\nHET:    MOV     R7,#48                  ; TI bật ở ĐẦU bit STOP: chờ thêm\n        DJNZ    R7,$                    ; 97 CK > 1 bit = 96 CK: STOP ra hết\n        CLR     P1.0                    ; rồi mới nhả đường dây\n        SJMP    $\nTL:     DB      'O','K',0DH,0\n        END\n","note":"Mở Đồ thị thời gian: P1.0 (DE) lên 1 trước khung đầu, TXD phát 'O', 'K', CR liền nhau; sau TI của byte cuối, DE còn giữ thêm 97 chu kỳ rồi mới về 0. Đoán trước: xóa hai dòng HET/DJNZ thì DE về 0 lúc nào so với bit STOP? (Ngay đầu bit STOP — cắt mất bit STOP.)","dev":{"led":true},"fosc":11059200,"speed":"real","watch":{"title":"Biến theo dõi","vars":[["P1 (DE = bit 0)",144,"hex"],["SCON",152,"hex"],["R0 (byte)",0,"dec"],["R7 (chờ)",7,"dec"]],"sfr":true,"hint":"Mở Đồ thị thời gian: P1.0 (DE) lên 1 trước bit START đầu tiên và chỉ về 0 sau khi bit STOP của byte cuối (0DH) ra hết trên TXD."}}];
const sim52=makeSim51(document.getElementById("m51-l52"),{id:"s52",presets:P52,ram:256});
makeEx51(document.getElementById("ex-l52"),"l52",[{"t":"Kiểm tra dòng lệnh ASCII","d":"<p>Giao thức HMI đơn giản: máy tính gửi dòng 3 byte, đã nằm ở <code>40H<\/code>–<code>42H<\/code>. Dòng hợp lệ khi: byte 1 là <code>'R'<\/code> (đọc) hoặc <code>'W'<\/code> (ghi) — chữ hoa; byte 2 là chữ số <code>'0'<\/code>…<code>'7'<\/code> (số thanh ghi); byte 3 là CR (<code>0DH<\/code>). Hợp lệ: <code>30H<\/code> = <code>01H<\/code>, <code>31H<\/code> = số thanh ghi (0…7). Không hợp lệ: <code>30H<\/code> = <code>00H<\/code>, <code>31H<\/code> = <code>FFH<\/code>. Ô 40H–42H giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: 40H..42H = <code>'R' '2' 0DH<\/code> → <code>30H = 01H<\/code>, <code>31H = 02H<\/code>.<\/p>","start":"; Kiểm tra dòng lệnh ASCII ở 40H..42H\n; Hợp lệ: 'R' hoặc 'W', '0'..'7', CR -> 30H = 01H, 31H = số\n        ORG     0000H\n        MOV     30H,#00H\n        MOV     31H,#0FFH\n        MOV     A,40H\n        CJNE    A,#'R',XONG             ; (chưa nhận lệnh 'W')\n        MOV     A,41H\n        CLR     C\n        SUBB    A,#'0'                  ; (chưa kiểm phạm vi, chưa kiểm CR)\n        MOV     31H,A\n        MOV     30H,#01H\nXONG:   SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x40":82,"0x41":50,"0x42":13,"0x30":90,"0x31":90}},"expect":{"iram":{"0x40":82,"0x41":50,"0x42":13,"0x30":1,"0x31":2}}},{"setup":{"iram":{"0x40":87,"0x41":55,"0x42":13,"0x30":90,"0x31":90}},"expect":{"iram":{"0x40":87,"0x41":55,"0x42":13,"0x30":1,"0x31":7}}},{"setup":{"iram":{"0x40":82,"0x41":48,"0x42":13,"0x30":90,"0x31":90}},"expect":{"iram":{"0x40":82,"0x41":48,"0x42":13,"0x30":1,"0x31":0}}},{"setup":{"iram":{"0x40":82,"0x41":56,"0x42":13,"0x30":90,"0x31":90}},"expect":{"iram":{"0x40":82,"0x41":56,"0x42":13,"0x30":0,"0x31":255}}},{"setup":{"iram":{"0x40":82,"0x41":47,"0x42":13,"0x30":90,"0x31":90}},"expect":{"iram":{"0x40":82,"0x41":47,"0x42":13,"0x30":0,"0x31":255}}},{"setup":{"iram":{"0x40":88,"0x41":49,"0x42":13,"0x30":90,"0x31":90}},"expect":{"iram":{"0x40":88,"0x41":49,"0x42":13,"0x30":0,"0x31":255}}},{"setup":{"iram":{"0x40":82,"0x41":51,"0x42":10,"0x30":90,"0x31":90}},"expect":{"iram":{"0x40":82,"0x41":51,"0x42":10,"0x30":0,"0x31":255}}},{"setup":{"iram":{"0x40":114,"0x41":51,"0x42":13,"0x30":90,"0x31":90}},"expect":{"iram":{"0x40":114,"0x41":51,"0x42":13,"0x30":0,"0x31":255}}}]},"hints":["Code mẫu chỉ nhận 'R', không kiểm CR và không kiểm phạm vi chữ số: chạy bộ thử 4, 5, 7.","Kiểm lệnh bằng hai CJNE ('R' rồi 'W'); kiểm 42H = 0DH; mọi nhánh sai nhảy thẳng tới SJMP $ (30H, 31H đã đặt sẵn giá trị “không hợp lệ” ở đầu).","Chữ số hợp lệ là '0'…'7': kiểm cả biên dưới và biên trên sau khi trừ '0'."],"why":"Bộ phân tích lệnh phải kiểm từng trường trước khi dùng: số thanh ghi ngoài phạm vi sẽ thành địa chỉ bảng sai (giống trạng thái ngoài bảng nhảy ở Bài 50). Gán sẵn kết quả “không hợp lệ” rồi chỉ ghi “hợp lệ” khi qua mọi kiểm tra giúp không bỏ sót nhánh."},{"t":"Lọc địa chỉ và mã hàm","d":"<p>Trạm Modbus RTU có địa chỉ ở <code>2FH<\/code> (1…247). Khung vừa nhận (CRC đã đúng): <code>40H<\/code> = địa chỉ, <code>41H<\/code> = mã hàm. Trạm chỉ hỗ trợ hàm <code>03H<\/code> (đọc thanh ghi) và <code>06H<\/code> (ghi một thanh ghi). Ghi quyết định vào <code>30H<\/code>: <code>00H<\/code> bỏ qua (khung của trạm khác, hoặc quảng bá không phải lệnh ghi); <code>01H<\/code> xử lý và trả lời (đúng địa chỉ, hàm 03/06); <code>02H<\/code> xử lý nhưng không trả lời (địa chỉ 0 = quảng bá, hàm 06); <code>03H<\/code> trả lời ngoại lệ (đúng địa chỉ, hàm khác) — khi đó <code>31H<\/code> = mã hàm OR <code>80H<\/code>, <code>32H<\/code> = <code>01H<\/code> (mã ngoại lệ “hàm không hỗ trợ”). Trường hợp 0, 1, 2 không đổi 31H, 32H. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: 2FH = 01H, khung 01H 03H → <code>30H = 01H<\/code>.<\/p>","start":"; Lọc khung Modbus: 2FH = địa chỉ trạm, 40H = địa chỉ khung,\n; 41H = mã hàm -> 30H = 0 bỏ qua, 1 trả lời, 2 quảng bá, 3 ngoại lệ\n        ORG     0000H\n        MOV     30H,#00H\n        MOV     A,40H\n        CJNE    A,2FH,XONG              ; (chưa xét địa chỉ quảng bá 0)\n        MOV     30H,#01H                ; (chưa xét mã hàm, chưa có ngoại lệ)\nXONG:   SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x2F":1,"0x40":1,"0x41":3,"0x30":165,"0x31":90,"0x32":90}},"expect":{"iram":{"0x2F":1,"0x40":1,"0x41":3,"0x30":1,"0x31":90,"0x32":90}}},{"setup":{"iram":{"0x2F":1,"0x40":1,"0x41":6,"0x30":165,"0x31":90,"0x32":90}},"expect":{"iram":{"0x2F":1,"0x40":1,"0x41":6,"0x30":1,"0x31":90,"0x32":90}}},{"setup":{"iram":{"0x2F":1,"0x40":2,"0x41":3,"0x30":165,"0x31":90,"0x32":90}},"expect":{"iram":{"0x2F":1,"0x40":2,"0x41":3,"0x30":0,"0x31":90,"0x32":90}}},{"setup":{"iram":{"0x2F":1,"0x40":0,"0x41":6,"0x30":165,"0x31":90,"0x32":90}},"expect":{"iram":{"0x2F":1,"0x40":0,"0x41":6,"0x30":2,"0x31":90,"0x32":90}}},{"setup":{"iram":{"0x2F":1,"0x40":0,"0x41":3,"0x30":165,"0x31":90,"0x32":90}},"expect":{"iram":{"0x2F":1,"0x40":0,"0x41":3,"0x30":0,"0x31":90,"0x32":90}}},{"setup":{"iram":{"0x2F":17,"0x40":17,"0x41":5,"0x30":165,"0x31":90,"0x32":90}},"expect":{"iram":{"0x2F":17,"0x40":17,"0x41":5,"0x30":3,"0x31":133,"0x32":1}}},{"setup":{"iram":{"0x2F":247,"0x40":247,"0x41":16,"0x30":165,"0x31":90,"0x32":90}},"expect":{"iram":{"0x2F":247,"0x40":247,"0x41":16,"0x30":3,"0x31":144,"0x32":1}}},{"setup":{"iram":{"0x2F":17,"0x40":1,"0x41":16,"0x30":165,"0x31":90,"0x32":90}},"expect":{"iram":{"0x2F":17,"0x40":1,"0x41":16,"0x30":0,"0x31":90,"0x32":90}}}]},"hints":["Xét địa chỉ 0 (quảng bá) TRƯỚC khi so với địa chỉ trạm: JZ ngay sau MOV A,40H.","So với địa chỉ trạm bằng CJNE A,2FH,… (so A với ô nhớ trực tiếp). Khác địa chỉ thì im lặng, kể cả khi mã hàm lạ (bộ thử 8).","Nhánh ngoại lệ trả mã hàm có bit 7 bật kèm mã ngoại lệ (xem mục về ngoại lệ Modbus trong bài)."],"why":"Trạm chỉ được trả lời khung gửi đúng cho nó; khung quảng bá không ai trả lời (nếu mọi trạm cùng trả lời thì đường truyền chung bị tranh chấp), nên lệnh đọc gửi quảng bá vô nghĩa. Mã hàm không hỗ trợ thì trả lời ngoại lệ để máy chủ biết lý do, thay vì im lặng làm máy chủ chờ hết thời gian."},{"t":"CRC-16 Modbus nhanh","d":"<p>Tính CRC-16 Modbus (đa thức đảo <code>A001H<\/code>, giá trị đầu <code>FFFFH<\/code>, xử lý từng bit từ bit thấp) của N byte: <code>3FH<\/code> = N (1…8), dữ liệu từ <code>40H<\/code>. Ghi byte thấp CRC vào <code>30H<\/code>, byte cao vào <code>31H<\/code>; dữ liệu và 3FH giữ nguyên. Code mẫu khởi tạo sai và chậm (mỗi bit 11 hoặc 15 chu kỳ). Chỉ tiêu: mọi bộ thử không quá <b>760 chu kỳ máy<\/b> (tính cả <code>SJMP $<\/code>) và mã không quá <b>40 byte<\/b>.<\/p><p>Ví dụ: N = 6, dữ liệu <code>01 03 00 00 00 01<\/code> → <code>30H = 84H<\/code>, <code>31H = 0AH<\/code> (gửi đi theo thứ tự 84 0A).<\/p>","start":"; CRC-16 Modbus của N byte (3FH = N, dữ liệu từ 40H)\n; Kết quả: 30H byte thấp, 31H byte cao. Code mẫu có lỗi và chậm.\n        ORG     0000H\n        MOV     R2,#00H                 ; CRC đầu (R3:R2)\n        MOV     R3,#00H\n        MOV     R0,#40H\n        MOV     R7,3FH\nVB:     MOV     A,@R0\n        XRL     A,R2\n        MOV     R2,A\n        MOV     R6,#8\nVT:     CLR     C\n        MOV     A,R3\n        RRC     A\n        MOV     R3,A\n        MOV     A,R2\n        RRC     A\n        MOV     R2,A\n        JNC     VK\n        XRL     02H,#01H\n        XRL     03H,#0A0H\nVK:     DJNZ    R6,VT\n        INC     R0\n        DJNZ    R7,VB\n        MOV     30H,R2\n        MOV     31H,R3\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x3F":6,"0x30":90,"0x31":90,"0x40":1,"0x41":3,"0x42":0,"0x43":0,"0x44":0,"0x45":1}},"expect":{"iram":{"0x3F":6,"0x30":132,"0x31":10,"0x40":1,"0x41":3,"0x42":0,"0x43":0,"0x44":0,"0x45":1}}},{"setup":{"iram":{"0x3F":1,"0x30":90,"0x31":90,"0x40":255}},"expect":{"iram":{"0x3F":1,"0x30":255,"0x31":0,"0x40":255}}},{"setup":{"iram":{"0x3F":1,"0x30":90,"0x31":90,"0x40":0}},"expect":{"iram":{"0x3F":1,"0x30":191,"0x31":64,"0x40":0}}},{"setup":{"iram":{"0x3F":6,"0x30":90,"0x31":90,"0x40":17,"0x41":3,"0x42":0,"0x43":107,"0x44":0,"0x45":3}},"expect":{"iram":{"0x3F":6,"0x30":118,"0x31":135,"0x40":17,"0x41":3,"0x42":0,"0x43":107,"0x44":0,"0x45":3}}},{"setup":{"iram":{"0x3F":8,"0x30":90,"0x31":90,"0x40":17,"0x41":3,"0x42":0,"0x43":107,"0x44":0,"0x45":3,"0x46":118,"0x47":135}},"expect":{"iram":{"0x3F":8,"0x30":0,"0x31":0,"0x40":17,"0x41":3,"0x42":0,"0x43":107,"0x44":0,"0x45":3,"0x46":118,"0x47":135}}},{"setup":{"iram":{"0x3F":5,"0x30":90,"0x31":90,"0x40":1,"0x41":3,"0x42":2,"0x43":1,"0x44":244}},"expect":{"iram":{"0x3F":5,"0x30":184,"0x31":83,"0x40":1,"0x41":3,"0x42":2,"0x43":1,"0x44":244}}},{"setup":{"iram":{"0x3F":8,"0x30":90,"0x31":90,"0x40":85,"0x41":170,"0x42":85,"0x43":170,"0x44":85,"0x45":170,"0x46":85,"0x47":170}},"expect":{"iram":{"0x3F":8,"0x30":21,"0x31":220,"0x40":85,"0x41":170,"0x42":85,"0x43":170,"0x44":85,"0x45":170,"0x46":85,"0x47":170}}}],"maxCyc":760,"maxBytes":40},"hints":["Sửa giá trị đầu thành FFFFH trước (bộ thử 1 phải ra 84H 0AH). Bộ thử 7 (N = 8) khi đó vẫn quá 760 chu kỳ.","Phần đắt nhất là vòng 8 bit chạy 8N lần. Giữ byte thấp CRC luôn trong A (XRL A,@R0 thay cho MOV A,@R0 / XRL A,R2 / MOV R2,A) và đổi chỗ với byte cao bằng XCH A,R3.","Mỗi bit chỉ còn một lần dịch phải 16 bit qua CY (hai byte, đổi chỗ bằng XCH) và một phép XOR có điều kiện với đa thức."],"why":"CRC theo bit tốn thời gian tỉ lệ 8N; bớt 2 chu kỳ mỗi bit tiết kiệm 128 chu kỳ cho khung 8 byte. Giữ một nửa CRC trong A và dùng XCH thay cho cặp MOV giảm cả số lệnh lẫn số byte (lời giải 34 byte, tối đa 734 chu kỳ ở bộ thử 7). Bộ thử 5 kiểm tính chất của CRC Modbus: CRC trên cả khung kèm 2 byte CRC đúng thứ tự (thấp trước) bằng 0000H — bên nhận dùng tính chất này để kiểm khung."}]);

/* Bảng “Sơ đồ trạng thái” của Chương 13 (sinh bởi tools/author/mcu8051/m13lib.py): đọc RAM của máy giả lập, không đổi trình mô phỏng. */
(function(){const R=document.getElementById("m51-l52"),PS=P52,H2=v=>v.toString(16).toUpperCase().padStart(2,"0");let pi=-1,sec=null,last=null,prevS=null,edge=-1,seen=null;
 function rd(m,a){if(typeof a==="string"){const x=/^([0-9A-F]+)H\.([0-7])$/i.exec(a);return x?(m.iram[parseInt(x[1],16)]>>+x[2])&1:0}return a>=0x80&&a<0x100&&PS[pi].watch.sfr?m.sfr[a-0x80]:m.iram[a]}
 function shape(w){if(!sec){sec=document.createElement("section");sec.className="pn m13-w";sec.innerHTML='<div class="pane-h"><span>Sơ đồ trạng thái</span><span class="m13-h"></span></div><div class="m51-sec m13-b"></div>';}
  const sc=R.querySelector(".st-scroll");if(sec.parentNode!==sc)sc.insertBefore(sec,sc.firstChild);sec.hidden=!w;if(!w)return;
  sec.querySelector(".pane-h span").textContent=w.title||"Sơ đồ trạng thái";
  let h="";if(w.states)h+='<div class="m13-st" role="list" aria-label="Các trạng thái">'+w.states.map((s,i)=>'<span class="s" role="listitem" data-s="'+i+'">'+s+'</span>').join("")+'</div>';
  if(w.edges)h+='<ul class="m13-ed">'+w.edges.map((e,i)=>'<li data-e="'+i+'">'+w.states[e[0]]+' → '+w.states[e[1]]+': '+e[2]+'</li>').join("")+'</ul>';
  if(w.vars)h+='<div class="m13-vr">'+w.vars.map((v,i)=>'<span data-v="'+i+'"><b>'+v[0]+'</b> <i>–</i></span>').join("")+'</div>';
  h+='<p class="m13-hint">'+(w.hint||"Trạng thái và biến đọc từ RAM trong sau mỗi lệnh; ô vừa đổi được tô màu.")+'</p>';
  sec.querySelector(".m13-b").innerHTML=h;last=null;prevS=null;edge=-1;seen=null}
 function paint(m){const w=PS[pi].watch;if(!w)return;const H=sec.querySelector(".m13-h");
  if(!m){H.textContent="chưa chạy";sec.querySelectorAll(".m13-st .s").forEach(x=>x.classList.remove("on","was"));sec.querySelectorAll(".m13-ed li").forEach(x=>x.classList.remove("on"));sec.querySelectorAll(".m13-vr i").forEach(x=>x.textContent="–");last=null;prevS=null;edge=-1;return}
  if(m!==seen){seen=m;last=null;prevS=null;edge=-1}
  const vals=(w.vars||[]).map(v=>rd(m,v[1]));
  if(w.states){const s=rd(m,w.state);if(prevS!=null&&s!==prevS&&w.edges){const k=w.edges.findIndex(e=>e[0]===prevS&&e[1]===s);if(k>=0)edge=k}
   sec.querySelectorAll(".m13-st .s").forEach(x=>{x.classList.toggle("on",+x.dataset.s===s);x.classList.toggle("was",prevS!=null&&+x.dataset.s===prevS&&s!==prevS)});
   sec.querySelectorAll(".m13-ed li").forEach(x=>x.classList.toggle("on",+x.dataset.e===edge));
   H.textContent=s<w.states.length?"trạng thái "+s+" · "+w.states[s].replace(/<[^>]+>/g,""):"trạng thái "+H2(s)+"H (ngoài bảng!)";if(s!==prevS)prevS=s}
  else H.textContent="t = "+(m.cyc*12/m.fosc*1000).toLocaleString("vi-VN",{maximumFractionDigits:3})+" ms";
  sec.querySelectorAll(".m13-vr span").forEach((x,i)=>{const v=vals[i],k=w.vars[i][2]||"hex";x.querySelector("i").textContent=k==="dec"?String(v):k==="bit"?String(v):H2(v)+"H ("+v+")";x.classList.toggle("chg",!!last&&last[i]!==v)});last=vals}
 function loop(){const sc=R&&R.querySelector(".st-scroll");if(sc){const sel=R.querySelector(".s-pre"),i=sel?+sel.value:0;
   if(i!==pi){pi=i;const p=PS[i]||{};const sp=R.querySelector(".m51-sp");if(sp&&p.speed)sp.value=p.speed;shape(p.watch);sec&&(seen=null)}
   else if(sec&&sec.parentNode!==sc)shape(PS[pi].watch);
   if(PS[pi]&&PS[pi].watch){let m=null;try{m=sim52.machine()}catch(e){}paint(m)}}
  setTimeout(loop,150)}
 if(R)loop()})();

makeQuiz("quiz52","score52",[{"q": "Tác vụ nhận lệnh trong firmware có bộ lập lịch hợp tác (Bài 49) nên đọc dòng lệnh từ máy tính thế nào?", "o": ["Mỗi tick lấy tối đa một byte và đưa vào máy trạng thái của bộ phân tích", "Chờ đủ dòng bằng JNB RI,$ rồi phân tích một lần", "Tắt ngắt Timer 0 trong lúc nhận để không mất byte", "Nhận cả dòng trong ISR UART rồi phân tích ngay trong ISR"], "a": 0, "e": "Chờ bằng JNB RI,$ chặn mọi tác vụ khác hàng chục ms; tắt ngắt timer làm lệch tick; phân tích trong ISR kéo dài thời gian ngắt. Máy trạng thái nhận từng byte giữ mọi tác vụ chạy đều."}, {"q": "Trạm Modbus RTU trả lời giá trị thanh ghi 01F4H, CRC của khung trả lời là 53B8H. Năm byte cuối của khung gửi đi là gì?", "o": ["01 F4 B8 53", "F4 01 B8 53", "01 F4 53 B8", "F4 01 53 B8"], "a": 0, "e": "Số 16 bit trong vùng dữ liệu gửi byte cao trước (01 F4); riêng CRC gửi byte thấp trước (B8 53). Đảo CRC thì bên nhận tính ra khác 0000H và bỏ khung (ví dụ 4)."}, {"q": "Máy chủ gửi khung có địa chỉ 0 (quảng bá), hàm 06 ghi một thanh ghi. Trạm số 5 nên làm gì?", "o": ["Thực hiện và trả lời như khung gửi riêng", "Bỏ qua vì địa chỉ 0 không phải của mình", "Thực hiện lệnh ghi nhưng không trả lời", "Trả lời ngoại lệ mã 01"], "a": 2, "e": "Quảng bá: mọi trạm thực hiện, không trạm nào trả lời (nếu không, mọi trạm cùng chiếm đường dây RS-485). Vì vậy chỉ lệnh ghi mới có ý nghĩa khi quảng bá (bài tập 2)."}, {"q": "Modbus RTU, 9600 baud, ký tự 11 bit (1 START, 8 dữ liệu, chẵn lẻ, 1 STOP). Khoảng lặng t3,5 dài khoảng bao nhiêu?", "o": ["≈ 3,6 ms", "≈ 4,0 ms", "≈ 0,36 ms", "1,75 ms"], "a": 1, "e": "Một ký tự 11/9600 = 1,146 ms; × 3,5 = 4,01 ms. 3,6 ms là kết quả nếu tính ký tự 10 bit (8N1); 0,36 ms là 3,5 bit; 1,75 ms là giá trị cố định chỉ dùng khi baud trên 19200."}, {"q": "Trạm dùng RS-485 bán song công, chân DE bật khi phát. Tắt DE lúc nào sau byte cuối của câu trả lời?", "o": ["Ngay khi TI của byte cuối bật", "Ngay sau lệnh ghi byte cuối vào SBUF", "Không cần tắt, để DE luôn bằng 1", "Sau khi bit STOP của byte cuối ra hết (TI bật + ít nhất một thời gian bit)"], "a": 3, "e": "TI bật ở đầu bit STOP, nên tắt DE ngay lúc đó cắt bit STOP. Tắt ngay sau khi ghi SBUF còn tệ hơn (cả byte chưa ra). Giữ DE = 1 mãi thì trạm khác và máy chủ không nói được nữa."}]);

